     "summary": "本报讯 （记者邢萌 见习记者张家毅）10月12日，国民信托有限公司（以下简称“国民信托”）公告称，该公司以30亿元未分配利润转增注册资本的事项已完成工商变更登记，其注册资本由10亿元升至40亿元，股东构成及持股比例保持不变。本次增资事项已于今年8月获国家金融监督管理总局北京监管局批准，并于9月29日完成工商登记。（编辑 张文玲）",
